		body.StatusReason = stringPtr(reason)
	}
	resp, err := client.Patch(ctx, trailReviewCommentPath(trailID, comment.ReviewID, comment.ID), body)
	if err != nil {
		return api.TrailReviewComment{}, fmt.Errorf("update finding: %w", err)
