func TestAgentPackages_SelfRegister(t *testing.T) {
	t.Parallel()

	agentDir := findAgentDir(t)
	agentPkgs := discoverAgentPackages(t, agentDir)

	if len(agentPkgs) == 0 {
		t.Fatal("no agent packages found — test setup is broken")
